import { Injectable,OnModuleDestroy,OnModuleInit } from '@nestjs/common';import { createClient } from 'redis';
@Injectable()export class CacheService implements OnModuleInit,OnModuleDestroy{private client=createClient({url:process.env.REDIS_URL??'redis://redis:6379'});async onModuleInit(){this.client.on('error',err=>console.error('Redis error',err));await this.client.connect()}async onModuleDestroy(){if(this.client.isOpen)await this.client.quit()}async hit(key:string,windowSeconds:number){const n=await this.client.incr(key);if(n===1)await this.client.expire(key,windowSeconds);return n}async getJson<T>(key:string){const x=await this.client.get(key);return x?JSON.parse(x) as T:null}async setJson(key:string,value:unknown,ttlSeconds:number){await this.client.set(key,JSON.stringify(value),{EX:ttlSeconds})}async del(key:string){await this.client.del(key)}async queuePush(key:string,value:unknown){await this.client.lPush(key,JSON.stringify(value))}async queuePop<T>(key:string){const value=await this.client.rPop(key);return value?JSON.parse(value) as T:null}}
